  4→fn chain_to_str(chain: &Chain) -> &'static str {
  5→    match chain {
  6→        Chain::Solana => "solana",
  7→        Chain::Hyperliquid => "hyperliquid",
  8→        Chain::Ethereum => "ethereum",
  9→    }
 10→}
