 12→fn str_to_chain(s: &str) -> anyhow::Result<Chain> {
 13→    match s {
 14→        "solana" => Ok(Chain::Solana),
 15→        "hyperliquid" => Ok(Chain::Hyperliquid),
 16→        "ethereum" => Ok(Chain::Ethereum),
 17→        _ => Err(anyhow::anyhow!("Unknown chain: {}", s)),
 18→    }
 19→}
