 21→fn entry_type_to_str(entry_type: &EntryType) -> &'static str {
 22→    match entry_type {
 23→        EntryType::Trade => "trade",
 24→        EntryType::Fee => "fee",
 25→        EntryType::Transfer => "transfer",
 26→        EntryType::Staking => "staking",
 27→        EntryType::Income => "income",
 28→    }
 29→}
