 31→fn str_to_entry_type(s: &str) -> EntryType {
 32→    match s {
 33→        "trade" => EntryType::Trade,
 34→        "fee" => EntryType::Fee,
 35→        "transfer" => EntryType::Transfer,
 36→        "staking" => EntryType::Staking,
 37→        "income" => EntryType::Income,
 38→        _ => EntryType::Transfer,
 39→    }
 40→}
