 42→pub fn build_checkpoint(
 43→    chain: &str,
 44→    wallet: &str,
 45→    txs: &[Transaction],
 46→) -> Option<IndexerCheckpoint> {
 47→    if txs.is_empty() {
 48→        return None;
 49→    }
 50→
 51→    let chain_enum = str_to_chain(chain).ok()?;
 52→    let latest = txs.iter().max_by_key(|tx| tx.timestamp)?;
 53→
 54→    let last_slot = match chain {
 55→        "solana" => txs
 56→            .iter()
 57→            .filter_map(|tx| tx.raw_metadata.get("slot").and_then(|v| v.as_i64()))
 58→            .max(),
 59→        _ => None,
 60→    };
 61→
 62→    let last_block = match chain {
 63→        "ethereum" => txs
 64→            .iter()
 65→            .filter_map(|tx| tx.raw_metadata.get("block_number").and_then(|v| v.as_i64()))
 66→            .max(),
 67→        _ => None,
 68→    };
 69→
 70→    Some(IndexerCheckpoint {
 71→        chain: chain_enum,
 72→        wallet_address: wallet.to_string(),
 73→        last_signature: Some(latest.tx_hash.clone()),
 74→        last_slot,
 75→        last_block,
 76→        last_timestamp: Some(latest.timestamp),
 77→    })
 78→}
