 99→    /// Batch size for chunked inserts.
100→    const BATCH_SIZE: usize = 500;
101→
102→    pub async fn save_transactions(&self, txs: &[Transaction]) -> anyhow::Result<()> {
103→        for chunk in txs.chunks(Self::BATCH_SIZE) {
104→            let (query, args) = Self::build_transaction_insert(chunk)?;
105→            sqlx::query_with(&query, args).execute(&self.pool).await?;
106→        }
107→        Ok(())
108→    }
