148→    pub async fn save_ledger_entries(&self, entries: &[LedgerEntry]) -> anyhow::Result<()> {
149→        for chunk in entries.chunks(Self::BATCH_SIZE) {
150→            let (query, args) = Self::build_ledger_insert(chunk)?;
151→            sqlx::query_with(&query, args).execute(&self.pool).await?;
152→        }
