156→    fn build_ledger_insert(
157→        chunk: &[LedgerEntry],
158→    ) -> anyhow::Result<(String, sqlx::postgres::PgArguments)> {
159→        let mut query = String::from(
160→            "INSERT INTO ledger_entries (id, transaction_id, user_id, wallet_address, asset_symbol, amount, entry_type, fiat_value) VALUES ",
161→        );
162→        let mut args = sqlx::postgres::PgArguments::default();
163→        for (i, entry) in chunk.iter().enumerate() {
164→            let entry_type_str = entry_type_to_str(&entry.entry_type);
165→            let base = i * 8;
166→            if i > 0 {
167→                query.push_str(", ");
168→            }
169→            query.push_str(&format!(
170→                "(${}, ${}, ${}, ${}, ${}, ${}, ${}::entry_type_enum, ${})",
171→                base + 1,
172→                base + 2,
173→                base + 3,
174→                base + 4,
175→                base + 5,
176→                base + 6,
177→                base + 7,
178→                base + 8
179→            ));
180→            use sqlx::Arguments;
181→            args.add(entry.id).map_err(|e| anyhow::anyhow!("{e}"))?;
182→            args.add(entry.transaction_id)
183→                .map_err(|e| anyhow::anyhow!("{e}"))?;
184→            args.add(entry.user_id)
185→                .map_err(|e| anyhow::anyhow!("{e}"))?;
186→            args.add(&entry.wallet_address)
187→                .map_err(|e| anyhow::anyhow!("{e}"))?;
188→            args.add(&entry.asset_symbol)
189→                .map_err(|e| anyhow::anyhow!("{e}"))?;
190→            args.add(&entry.amount)
191→                .map_err(|e| anyhow::anyhow!("{e}"))?;
192→            args.add(entry_type_str)
193→                .map_err(|e| anyhow::anyhow!("{e}"))?;
194→            args.add(&entry.fiat_value)
195→                .map_err(|e| anyhow::anyhow!("{e}"))?;
196→        }
197→        query.push_str(" ON CONFLICT (id) DO NOTHING");
198→        Ok((query, args))
199→    }
