219→    pub async fn get_transactions_by_wallet_filtered(
220→        &self,
221→        wallet: &str,
222→        limit: i64,
223→        offset: i64,
224→        from: Option<i64>,
225→        to: Option<i64>,
226→    ) -> anyhow::Result<Vec<Transaction>> {
227→        let mut sql = String::from(
228→            "SELECT id, user_id, wallet_address, timestamp, tx_hash, chain::text, raw_metadata \
229→             FROM transactions WHERE wallet_address = $1",
230→        );
231→        if from.is_some() {
232→            sql.push_str(" AND timestamp >= $4");
233→        }
234→        if to.is_some() {
235→            sql.push_str(if from.is_some() {
236→                " AND timestamp <= $5"
237→            } else {
238→                " AND timestamp <= $4"
239→            });
240→        }
241→        sql.push_str(" ORDER BY timestamp ASC LIMIT $2 OFFSET $3");
242→
243→        let mut query = sqlx::query(&sql).bind(wallet).bind(limit).bind(offset);
244→        if let Some(f) = from {
245→            query = query.bind(f);
246→        }
247→        if let Some(t) = to {
248→            query = query.bind(t);
249→        }
250→        let rows = query.fetch_all(&self.pool).await?;
251→
252→        let mut txs = Vec::new();
253→        for row in rows {
254→            let chain_str: String = row.try_get("chain")?;
255→            let chain = str_to_chain(&chain_str)?;
256→
257→            txs.push(Transaction {
258→                id: row.try_get("id")?,
259→                user_id: row.try_get("user_id")?,
260→                wallet_address: row.try_get("wallet_address")?,
261→                timestamp: row.try_get("timestamp")?,
262→                tx_hash: row.try_get("tx_hash")?,
263→                chain,
264→                raw_metadata: row.try_get("raw_metadata")?,
265→            });
266→        }
267→        Ok(txs)
268→    }
