288→    pub async fn get_ledger_entries_by_wallet_filtered(
289→        &self,
290→        wallet: &str,
291→        limit: i64,
292→        offset: i64,
293→        from: Option<i64>,
294→        to: Option<i64>,
295→    ) -> anyhow::Result<Vec<LedgerEntry>> {
296→        let mut sql = String::from(
297→            "SELECT l.id, l.transaction_id, l.user_id, l.wallet_address, l.asset_symbol, \
298→             l.amount, l.entry_type::text, l.fiat_value \
299→             FROM ledger_entries l",
300→        );
301→        let needs_join = from.is_some() || to.is_some();
302→        if needs_join {
303→            sql.push_str(" JOIN transactions t ON l.transaction_id = t.id");
304→        }
305→        sql.push_str(" WHERE l.wallet_address = $1");
306→        let mut param_idx = 4_usize;
307→        if from.is_some() {
308→            sql.push_str(&format!(" AND t.timestamp >= ${param_idx}"));
309→            param_idx += 1;
310→        }
311→        if to.is_some() {
312→            sql.push_str(&format!(" AND t.timestamp <= ${param_idx}"));
313→        }
314→        sql.push_str(" ORDER BY l.created_at ASC LIMIT $2 OFFSET $3");
315→
316→        let mut query = sqlx::query(&sql).bind(wallet).bind(limit).bind(offset);
317→        if let Some(f) = from {
318→            query = query.bind(f);
319→        }
320→        if let Some(t) = to {
321→            query = query.bind(t);
322→        }
323→        let rows = query.fetch_all(&self.pool).await?;
324→
325→        let mut entries = Vec::new();
326→        for row in rows {
327→            let entry_type_str: String = row.try_get("entry_type")?;
328→            let entry_type = str_to_entry_type(&entry_type_str);
329→
330→            entries.push(LedgerEntry {
331→                id: row.try_get("id")?,
332→                transaction_id: row.try_get("transaction_id")?,
333→                user_id: row.try_get("user_id")?,
334→                wallet_address: row.try_get("wallet_address")?,
335→                asset_symbol: row.try_get("asset_symbol")?,
336→                amount: row.try_get("amount")?,
337→                entry_type,
338→                fiat_value: row.try_get("fiat_value")?,
339→            });
340→        }
341→        Ok(entries)
342→    }
