463→    pub async fn get_wallet_stats(&self, wallet: &str) -> anyhow::Result<WalletStatsRow> {
464→        let row = sqlx::query(
465→            r#"
466→            SELECT
467→                COUNT(*) AS tx_count,
468→                MIN(timestamp) AS earliest_timestamp,
469→                MAX(timestamp) AS latest_timestamp,
470→                COUNT(DISTINCT chain::text) AS chain_count
471→            FROM transactions
472→            WHERE wallet_address = $1
473→            "#,
474→        )
475→        .bind(wallet)
476→        .fetch_one(&self.pool)
477→        .await?;
478→
479→        let tx_count: i64 = row.try_get("tx_count")?;
480→        let earliest_timestamp: Option<i64> = row.try_get("earliest_timestamp")?;
481→        let latest_timestamp: Option<i64> = row.try_get("latest_timestamp")?;
482→        let chain_count: i64 = row.try_get("chain_count")?;
483→
484→        let unique_assets: i64 = sqlx::query(
485→            r#"
486→            SELECT COUNT(DISTINCT asset_symbol) AS unique_assets
487→            FROM ledger_entries
488→            WHERE wallet_address = $1
489→            "#,
490→        )
491→        .bind(wallet)
492→        .fetch_one(&self.pool)
493→        .await?
494→        .try_get("unique_assets")?;
495→
496→        let chain_tx_counts = sqlx::query(
497→            r#"
498→            SELECT chain::text AS chain, COUNT(*) AS count
499→            FROM transactions
500→            WHERE wallet_address = $1
501→            GROUP BY chain
502→            ORDER BY chain
503→            "#,
504→        )
505→        .bind(wallet)
506→        .fetch_all(&self.pool)
507→        .await?;
508→
509→        let mut per_chain: Vec<(String, i64)> = Vec::new();
510→        for r in chain_tx_counts {
511→            let chain: String = r.try_get("chain")?;
512→            let count: i64 = r.try_get("count")?;
513→            per_chain.push((chain, count));
514→        }
515→
516→        Ok(WalletStatsRow {
517→            tx_count,
518→            earliest_timestamp,
519→            latest_timestamp,
520→            chain_count,
521→            unique_assets,
522→            per_chain,
523→        })
524→    }
