530→    pub async fn save_checkpoint_with<'e, E>(
531→        executor: E,
532→        checkpoint: &IndexerCheckpoint,
533→    ) -> anyhow::Result<()>
534→    where
535→        E: Executor<'e, Database = Postgres>,
536→    {
537→        let chain_str = chain_to_str(&checkpoint.chain);
538→
539→        sqlx::query(
540→            r#"
541→            INSERT INTO indexer_checkpoints (chain, wallet_address, last_signature, last_slot, last_block, last_timestamp, updated_at)
542→            VALUES ($1::chain_enum, $2, $3, $4, $5, $6, NOW())
543→            ON CONFLICT (chain, wallet_address)
544→            DO UPDATE SET
545→                last_signature = EXCLUDED.last_signature,
546→                last_slot = EXCLUDED.last_slot,
547→                last_block = EXCLUDED.last_block,
548→                last_timestamp = EXCLUDED.last_timestamp,
549→                updated_at = NOW()
550→            "#,
551→        )
552→        .bind(chain_str)
553→        .bind(&checkpoint.wallet_address)
554→        .bind(&checkpoint.last_signature)
555→        .bind(checkpoint.last_slot)
556→        .bind(checkpoint.last_block)
557→        .bind(checkpoint.last_timestamp)
558→        .execute(executor)
559→        .await?;
560→
561→        Ok(())
562→    }
