565→        executor: E,
566→        txs: &[Transaction],
567→    ) -> anyhow::Result<()>
568→    where
569→        E: Executor<'e, Database = Postgres>,
570→    {
571→        let mut query = String::from(
572→            "INSERT INTO transactions (id, user_id, wallet_address, timestamp, tx_hash, chain, raw_metadata) VALUES ",
573→        );
