  1→use std::collections::{HashMap, HashSet};
  2→use std::num::NonZeroU32;
  3→use std::sync::Arc;
  4→use std::time::Duration;
  5→
  6→use alloy::consensus::Transaction as TransactionTrait;
  7→use alloy::primitives::{Address, B256};
  8→use alloy::providers::{Provider, ProviderBuilder};
  9→use alloy::rpc::types::{Filter, Log};
 10→use governor::{Quota, RateLimiter};
 11→use serde_json::json;
 12→use spectraplex_core::models::{Chain, ChainIngestor, IndexerCheckpoint, Transaction};
 13→use tracing::warn;
 14→use uuid::Uuid;
 15→
 16→/// Maximum block range per eth_getLogs request.
 17→const DEFAULT_BLOCK_CHUNK: u64 = 2000;
 18→
 19→/// EVM chain adapter that fetches logs and transactions via JSON-RPC.
 20→pub struct EvmAdapter {
 21→    provider: Arc<dyn Provider + Send + Sync>,
 22→    rate_limiter: Arc<
 23→        RateLimiter<
 24→            governor::state::NotKeyed,
 25→            governor::state::InMemoryState,
 26→            governor::clock::DefaultClock,
 27→        >,
 28→    >,
 29→    block_chunk: u64,
 30→}
 31→
 32→impl EvmAdapter {
 33→    /// Create a new adapter connected to an EVM-compatible RPC endpoint.
 34→    pub fn new(rpc_url: &str) -> anyhow::Result<Self> {
 35→        let url: reqwest::Url = rpc_url.parse()?;
 36→        let client = reqwest::Client::builder()
 37→            .timeout(Duration::from_secs(30))
 38→            .connect_timeout(Duration::from_secs(10))
 39→            .build()?;
 40→        let provider = ProviderBuilder::new().connect_reqwest(client, url);
 41→
 42→        // 5 requests per second by default (safe for public RPCs)
 43→        let quota = Quota::per_second(NonZeroU32::new(5).unwrap());
 44→        let limiter = RateLimiter::direct(quota);
 45→
 46→        Ok(Self {
 47→            provider: Arc::new(provider),
 48→            rate_limiter: Arc::new(limiter),
 49→            block_chunk: DEFAULT_BLOCK_CHUNK,
 50→        })
 51→    }
 52→
 53→    /// Set a custom block chunk size for `eth_getLogs` range queries.
 54→    pub fn with_block_chunk(mut self, chunk: u64) -> Self {
 55→        self.block_chunk = chunk;
 56→        self
 57→    }
 58→
 59→    /// Fetch logs for a given address across a block range, chunked to avoid
 60→    /// RPC limits.
 61→    pub async fn fetch_logs(
 62→        &self,
 63→        address: Address,
 64→        from_block: u64,
 65→        to_block: u64,
 66→    ) -> anyhow::Result<Vec<Log>> {
 67→        let mut all_logs = Vec::new();
 68→        let mut start = from_block;
 69→
 70→        while start <= to_block {
 71→            let end = std::cmp::min(start + self.block_chunk - 1, to_block);
 72→
 73→            self.rate_limiter.until_ready().await;
 74→
 75→            let filter = Filter::new()
 76→                .address(address)
 77→                .from_block(start)
 78→                .to_block(end);
 79→
 80→            let logs = self.provider.get_logs(&filter).await?;
 81→            all_logs.extend(logs);
 82→
 83→            start = end + 1;
 84→        }
 85→
 86→        Ok(all_logs)
 87→    }
 88→
 89→    /// Check block parent hash continuity for reorg detection.
 90→    /// Returns `Some(fork_block)` if a reorg is detected, starting from
 91→    /// the block where parent_hash diverges.
 92→    pub async fn detect_reorg(
 93→        &self,
 94→        known_blocks: &[(u64, B256)], // (block_num, block_hash) sorted ascending
 95→    ) -> anyhow::Result<Option<u64>> {
 96→        for (block_num, known_hash) in known_blocks.iter().rev() {
 97→            self.rate_limiter.until_ready().await;
 98→
 99→            if let Some(block) = self
100→                .provider
101→                .get_block_by_number((*block_num).into())
102→                .await?
103→            {
104→                if block.header.hash != *known_hash {
105→                    return Ok(Some(*block_num));
106→                }
107→            }
108→        }
109→        Ok(None)
110→    }
