 77→/// The Yellowstone gRPC adapter for real-time Solana transaction streaming.
 78→///
 79→/// Supports two modes:
 80→/// - `fetch_history`: one-shot subscription that collects up to `limit` transactions
 81→/// - `stream_transactions`: long-running streaming via a bounded channel
 82→pub struct SolanaGrpcAdapter {
 83→    config: GrpcStreamConfig,
 84→    checkpoint: SlotCheckpoint,
 85→}
 86→
 87→impl SolanaGrpcAdapter {
 88→    pub fn new(endpoint: &str, x_token: Option<String>) -> Self {
 89→        Self {
 90→            config: GrpcStreamConfig {
 91→                endpoint: endpoint.to_string(),
 92→                x_token,
 93→                ..Default::default()
 94→            },
 95→            checkpoint: SlotCheckpoint::new(),
 96→        }
 97→    }
 98→
 99→    pub fn with_config(config: GrpcStreamConfig) -> Self {
100→        Self {
101→            config,
102→            checkpoint: SlotCheckpoint::new(),
103→        }
104→    }
105→
106→    pub fn set_program_ids(&mut self, program_ids: Vec<String>) {
107→        self.config.program_ids = program_ids;
108→    }
109→
110→    pub fn checkpoint(&self) -> &SlotCheckpoint {
111→        &self.checkpoint
112→    }
113→
114→    /// Build the gRPC subscription request filtered by program IDs.
115→    fn build_subscribe_request(&self, from_slot: Option<u64>) -> SubscribeRequest {
116→        let mut transactions = HashMap::new();
117→        transactions.insert(
118→            "tx_filter".to_string(),
119→            SubscribeRequestFilterTransactions {
120→                vote: Some(false),
121→                failed: Some(false),
122→                account_include: self.config.program_ids.clone(),
123→                account_exclude: vec![],
124→                account_required: vec![],
125→                signature: None,
126→            },
127→        );
128→
129→        SubscribeRequest {
130→            accounts: HashMap::new(),
131→            slots: HashMap::new(),
132→            transactions,
133→            transactions_status: HashMap::new(),
134→            blocks: HashMap::new(),
135→            blocks_meta: HashMap::new(),
136→            entry: HashMap::new(),
137→            commitment: Some(self.config.commitment as i32),
138→            accounts_data_slice: vec![],
139→            ping: None,
140→            from_slot,
141→        }
142→    }
143→
144→    async fn connect_client(
145→        &self,
146→    ) -> anyhow::Result<GeyserGrpcClient<impl yellowstone_grpc_client::Interceptor + Clone>> {
147→        let builder = GeyserGrpcClient::build_from_shared(self.config.endpoint.clone())?
148→            .x_token(self.config.x_token.clone())?
149→            .connect_timeout(Duration::from_secs(10))
150→            .timeout(Duration::from_secs(10))
151→            .max_decoding_message_size(64 * 1024 * 1024);
152→
153→        let client = builder.connect().await?;
154→        Ok(client)
155→    }
156→
157→    /// Start a long-running streaming task. Returns a receiver for transactions
158→    /// and a JoinHandle for the background task.
159→    ///
160→    /// The stream will automatically reconnect on failure with exponential backoff,
161→    /// resuming from the last checkpointed slot.
162→    pub fn stream_transactions(
163→        &self,
164→    ) -> (mpsc::Receiver<Transaction>, tokio::task::JoinHandle<()>) {
165→        let (tx, rx) = mpsc::channel(self.config.channel_capacity);
166→        let config_endpoint = self.config.endpoint.clone();
167→        let config_x_token = self.config.x_token.clone();
168→        let config_program_ids = self.config.program_ids.clone();
169→        let config_commitment = self.config.commitment;
170→        let config_max_retries = self.config.max_retries;
171→        let checkpoint = self.checkpoint.clone();
172→
173→        let handle = tokio::spawn(async move {
174→            let adapter = SolanaGrpcAdapter {
175→                config: GrpcStreamConfig {
176→                    endpoint: config_endpoint,
177→                    x_token: config_x_token,
178→                    program_ids: config_program_ids,
179→                    commitment: config_commitment,
180→                    max_retries: config_max_retries,
181→                    ..Default::default()
182→                },
183→                checkpoint: checkpoint.clone(),
184→            };
185→
186→            let mut retry_count: u32 = 0;
187→
188→            loop {
189→                let from_slot = {
190→                    let last = checkpoint.get();
191→                    if last > 0 {
192→                        Some(last)
193→                    } else {
194→                        None
195→                    }
196→                };
197→
198→                info!(
199→                    "Connecting to gRPC endpoint: {} (from_slot: {:?}, attempt: {})",
200→                    adapter.config.endpoint,
201→                    from_slot,
202→                    retry_count + 1,
203→                );
204→
205→                match adapter.run_stream(&tx, from_slot).await {
206→                    Ok(()) => {
207→                        info!("gRPC stream ended normally");
208→                        break;
209→                    }
210→                    Err(e) => {
211→                        error!("gRPC stream error: {}", e);
212→                        retry_count += 1;
213→                        if retry_count > config_max_retries {
214→                            error!(
215→                                "Exceeded max retries ({}). Stopping gRPC stream.",
216→                                config_max_retries
217→                            );
218→                            break;
219→                        }
220→                        let backoff = Duration::from_secs(2u64.saturating_pow(retry_count.min(6)));
221→                        warn!(
222→                            "Reconnecting in {:?} (retry {}/{})",
223→                            backoff, retry_count, config_max_retries
224→                        );
225→                        tokio::time::sleep(backoff).await;
226→                    }
227→                }
228→            }
229→        });
230→
231→        (rx, handle)
232→    }
233→
234→    async fn run_stream(
235→        &self,
236→        tx: &mpsc::Sender<Transaction>,
237→        from_slot: Option<u64>,
238→    ) -> anyhow::Result<()> {
239→        let mut client = self.connect_client().await?;
240→        let request = self.build_subscribe_request(from_slot);
241→        let mut stream = client.subscribe_once(request).await?;
242→
243→        info!("gRPC subscription established");
244→
245→        while let Some(msg) = stream.next().await {
246→            let update = msg?;
247→
248→            match update.update_oneof {
249→                Some(UpdateOneof::Transaction(tx_update)) => {
250→                    let slot = tx_update.slot;
251→                    self.checkpoint.update(slot);
252→
253→                    if let Some(tx_info) = tx_update.transaction {
254→                        match convert_grpc_transaction(&tx_info, slot) {
255→                            Ok(transaction) => {
256→                                if tx.send(transaction).await.is_err() {
257→                                    info!("Channel receiver dropped, stopping stream");
258→                                    return Ok(());
259→                                }
260→                            }
261→                            Err(e) => {
262→                                warn!("Failed to convert gRPC transaction: {}", e);
263→                            }
264→                        }
265→                    }
266→                }
267→                Some(UpdateOneof::Ping(_)) => {
268→                    // Pings are keepalives, no action needed
269→                }
270→                _ => {
271→                    // Ignore other update types (slots, blocks, etc.)
272→                }
273→            }
274→        }
275→
276→        Ok(())
277→    }
278→}
279→
280→#[async_trait::async_trait]
281→impl ChainIngestor for SolanaGrpcAdapter {
282→    /// One-shot fetch: subscribes to the gRPC stream and collects up to `limit` transactions.
283→    ///
284→    /// The `wallet` parameter is used as the wallet_address on collected transactions.
285→    /// For real-time streaming, use `stream_transactions()` instead.
286→    async fn fetch_history(
287→        &self,
288→        wallet: &str,
289→        limit: usize,
290→        user_id: Uuid,
291→        _checkpoint: Option<&IndexerCheckpoint>,
292→    ) -> anyhow::Result<Vec<Transaction>> {
293→        let mut client = self.connect_client().await?;
294→
295→        let from_slot = {
296→            let last = self.checkpoint.get();
297→            if last > 0 {
298→                Some(last)
299→            } else {
300→                None
301→            }
302→        };
303→        let request = self.build_subscribe_request(from_slot);
304→        let mut stream = client.subscribe_once(request).await?;
305→
306→        info!(
307→            "gRPC fetch_history: subscribing for up to {} transactions (wallet: {})",
308→            limit, wallet
309→        );
310→
311→        let mut transactions = Vec::new();
312→
313→        while let Some(msg) = stream.next().await {
314→            let update = msg?;
315→
316→            if let Some(UpdateOneof::Transaction(tx_update)) = update.update_oneof {
317→                let slot = tx_update.slot;
318→                self.checkpoint.update(slot);
319→
320→                if let Some(tx_info) = tx_update.transaction {
321→                    match convert_grpc_transaction(&tx_info, slot) {
322→                        Ok(mut transaction) => {
323→                            transaction.wallet_address = wallet.to_string();
324→                            transaction.user_id = user_id;
325→                            transactions.push(transaction);
326→
327→                            if transactions.len() >= limit {
328→                                break;
329→                            }
330→                        }
331→                        Err(e) => {
332→                            warn!("Failed to convert gRPC transaction: {}", e);
333→                        }
334→                    }
335→                }
336→            }
337→        }
338→
339→        info!(
340→            "gRPC fetch_history: collected {} transactions",
341→            transactions.len()
342→        );
343→        Ok(transactions)
344→    }
345→}
